    major, minor, patch = (int(part) for part in main.split("."))

    if separator:
        identifiers = prerelease.split(".")
    else:
        identifiers = None

    return major, minor, patch, identifiers


def _is_numeric(identifier):
    return identifier.isdigit()


def _compare(left, right):
    left_parts = _parse(left)
    right_parts = _parse(right)

    for left_number, right_number in zip(left_parts[:3], right_parts[:3]):
        if left_number != right_number:
            return -1 if left_number < right_number else 1

    left_pre = left_parts[3]
    right_pre = right_parts[3]

    if left_pre is None and right_pre is None:
        return 0
    if left_pre is None:
        return 1
    if right_pre is None:
        return -1

    for left_id, right_id in zip(left_pre, right_pre):
        if left_id == right_id:
            continue

        left_numeric = _is_numeric(left_id)
        right_numeric = _is_numeric(right_id)

        if left_numeric and right_numeric:
            return -1 if int(left_id) < int(right_id) else 1
        if left_numeric:
            return -1
        if right_numeric:
            return 1

        return -1 if left_id < right_id else 1

    if len(left_pre) < len(right_pre):
        return -1
    if len(left_pre) > len(right_pre):
        return 1
    return 0


def sort_versions(vs):
